/// Cerca in kGifCatalog per nome esatto o parziale.
ExerciseInfo? findInGifCatalog(String query) {
  final q = normalizeExerciseLookup(query);
  // Exact match canonico: nome, nome EN, slug GIF
  for (final e in kGifCatalog) {
    if (normalizeExerciseLookup(e.name) == q ||
        normalizeExerciseLookup(e.nameEn) == q ||
        normalizeExerciseLookup(e.gifSlug) == q) {
      return e;
    }
  }
  // Partial match (ogni parola del query presente nel nome)
  final words = q.split(' ').where((w) => w.length > 2).toList();
  if (words.isNotEmpty) {
    for (final e in kGifCatalog) {
      final candidates = <String>[
        normalizeExerciseLookup(e.name),
        normalizeExerciseLookup(e.nameEn),
        normalizeExerciseLookup(e.gifSlug),
      ];
      if (candidates.any((candidate) => words.every(candidate.contains))) {
        return e;
      }
    }
  }
  return null;
}

ExerciseInfo? findInGifCatalogExact(String query) {
  final q = normalizeExerciseLookup(query);
  for (final e in kGifCatalog) {
    if (normalizeExerciseLookup(e.name) == q ||
        normalizeExerciseLookup(e.nameEn) == q ||
        normalizeExerciseLookup(e.gifSlug) == q) {
      return e;
    }
  }
  return null;
}

/// Cerca un ExerciseInfo tramite il suo gifFilename (slug, es. 'barbell-curl').
/// Utile quando il PT ha assegnato una GIF custom a un esercizio non in catalogo.
ExerciseInfo? findByGifSlug(String slug) {
  final s = normalizeExerciseLookup(slug);
  for (final e in kGifCatalog) {
    if (normalizeExerciseLookup(e.gifSlug) == s) return e;
  }
  for (final e in kExerciseCatalog) {
    if (normalizeExerciseLookup(e.gifSlug) == s) return e;
  }
  return null;
}

/// Risoluzione canonica: prima slug/nome GIF, poi catalogo locale per nome/alias esatti.
ExerciseInfo? findAnyExercise(String name) {
  return findByGifSlug(name) ??
      findInGifCatalogExact(name) ??
      findExercise(name);
}

/// Lista di tutti i GIF disponibili (slug senza .gif), ordinati alfabeticamente.
/// Usata dal GIF picker nel PT app.
List<String> get allGifSlugs => kGifCatalog.map((e) => e.gifFilename!).toList();
